// The element trees: the pane (both kinds of surface) and the band strip.
// Everything shown is the server's `sheet` and `derived`; the only arithmetic
// is "left = max − used" for slots, pips and Hit Dice. Pure: the elements come
// in from register.ts, which owns every mods API call and handles the presses.
//
// The pane is built around a player's turn, not the sheet's sections:
// - the HUD, always visible: name and level, conditions when there are any,
//   HP as the hero, AC · INIT · SPD · spell DC and attack per caster, slot
//   pips, resources;
// - one row of tabs, one open at a time, by the player's question: Actions
//   (the turn menu: what can I do, what do I roll?), Saves & skills,
//   Features, Gear, Notes;
// - a quiet line at the bottom saying how fresh the numbers are.
// Pixel type is only for numerals and two-to-four-letter labels; every word
// is Text, readable and theme-aware. Ornaments (section marks, rules, action
// icons, badges) are Svg on Desktop and Raster cells in the terminal (Paint).

import type { ButtonProps, Elements, RenderElement, RenderNode, TextProps } from 'claude-code'
import { describeChange, type Entry } from './sheet.ts'
import { actionGroups, rowText, type ActionRow } from './actions.ts'
import {
  ART_FLOOR, ART_MAX, badgeSvg, C, classAccent, hpBarCells, hpColour, hudSvg, iconCells, iconSvg, markCells, markSvg, packCells, pipCells, pipsSvg, ruleSvg, savesSvg,
  type Cell, type Hud,
} from './art.ts'

/** What `$.ui.resolve(e)` hands out, on any surface. */
export type Els = Elements[keyof Elements]

/** The elements every surface has, which the shared parts of the pane draw with. */
type Base = Pick<Elements['mobile'], 'Box' | 'Text' | 'Button' | 'Markdown'>

/** The tabs, by the player's question. Hotkeys leave `d h r u t` free for later taps. */
export const TABS = [
  { id: 'actions', label: 'Actions', hotkey: 'a', words: ['actions', 'action', 'spells', 'attacks'] },
  { id: 'saves', label: 'Saves', hotkey: 's', words: ['saves', 'save', 'skills', 'checks'] },
  { id: 'features', label: 'Features', hotkey: 'f', words: ['features', 'feats', 'traits'] },
  { id: 'gear', label: 'Gear', hotkey: 'g', words: ['gear', 'inventory', 'items', 'money'] },
  { id: 'notes', label: 'Notes', hotkey: 'n', words: ['notes', 'rules', 'character', 'details'] },
] as const
export type TabId = (typeof TABS)[number]['id']

/** The tab a word names (`spells`, `saves`, `g`), or null. */
export function tabOf(word: string): TabId | null {
  const w = word.trim().toLowerCase()
  return TABS.find((t) => t.id === w || t.hotkey === w || (t.words as readonly string[]).includes(w))?.id ?? null
}

/** The key of the DM-rules badge, which opens the Notes tab. */
export const RULES_KEY = 'dm-rules'
export const tabKey = (id: TabId) => 'tab-' + id

export interface PaneView {
  entry: Entry | null
  surface: string
  columns: number
  tab: TabId
  /** Milliseconds since the epoch, for the freshness line ("Read 13:19" on the day it was read). */
  now: number
  /**
   * Buttons kept from this surface's last drawing. An unchanged Button is
   * handed back as the same element, so its press handle survives the redraw
   * (each new Button gets a new handle, and the old one is retired).
   */
  memo: Map<string, RenderElement>
}

const signed = (n: unknown) => (typeof n === 'number' ? (n >= 0 ? '+' + n : String(n)) : '?')
const pad2 = (n: number) => String(n).padStart(2, '0')
const clock = (ms: number) => {
  const d = new Date(ms)
  return pad2(d.getHours()) + ':' + pad2(d.getMinutes())
}
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const day = (ms: number) => {
  const d = new Date(ms)
  return `${d.getDate()} ${MONTHS[d.getMonth()]}, ${clock(ms)}`
}
const sameDay = (a: number, b: number) => new Date(a).toDateString() === new Date(b).toDateString()
const RECHARGE: Record<string, string> = { short: 'short rest', long: 'long rest', dawn: 'dawn', none: 'no recharge' }
const ORDINAL = (l: string) => ({ '1': '1st', '2': '2nd', '3': '3rd' })[l] ?? l + 'th'
const ABBR: Record<string, string> = {
  artificer: 'ART', barbarian: 'BBN', bard: 'BRD', cleric: 'CLR', druid: 'DRU', fighter: 'FTR', monk: 'MNK',
  paladin: 'PAL', ranger: 'RGR', rogue: 'ROG', sorcerer: 'SOR', warlock: 'WLK', wizard: 'WIZ',
}
const abbr = (cls: string) => ABBR[cls.toLowerCase()] ?? cls.slice(0, 3).toUpperCase()
const ABILITIES = ['str', 'dex', 'con', 'int', 'wis', 'cha'] as const

// ------------------------------------------------------------------ facts (read off the entry)

const unresolvedName = (name: string, unresolved: string[]) =>
  unresolved.some((u) => u.toLowerCase() === name.toLowerCase() || u.toLowerCase().endsWith(' ' + name.toLowerCase()))

function level(e: Entry): string {
  const total = e.derived?.total_level
  return (typeof total === 'number' ? String(total) : '?') + (e.derivedPending && typeof total === 'number' ? '?' : '')
}

/** `Lv 2 · Sorcerer 1 · Cleric 1`: level once, classes without subclasses (those are in Features). */
function identityLine(e: Entry): string {
  const classes = (e.sheet.classes ?? []).map((c: any) => `${c.name} ${c.level}`)
  return [`Lv ${level(e)}`, ...classes].join(' · ')
}

interface Caster {
  cls: string
  dc: string
  attack: string
}

function casters(e: Entry): Caster[] {
  return ((e.derived?.spellcasting ?? []) as any[]).map((c) => ({ cls: String(c.class), dc: String(c.save_dc ?? '?'), attack: String(c.attack ?? '?') }))
}

interface Pips {
  label: string
  left: number
  max: number
  pending: boolean
}

/** Slot rows by level, `1` → `{label: '1st'}`; pact slots last. */
function slotRows(e: Entry): (Pips & { level: number })[] {
  const used = e.sheet.spellcasting?.slots_used ?? {}
  const pending = e.derivedPending
  const rows = Object.entries((e.derived?.spell_slots ?? {}) as Record<string, number>)
    .sort(([a], [b]) => Number(a) - Number(b))
    .map(([lvl, max]) => ({ label: ORDINAL(lvl), level: Number(lvl), max, left: Math.max(0, max - (used[lvl] ?? 0)), pending }))
  const pact = e.derived?.pact_slots
  if (pact && typeof pact.slots === 'number') {
    const left = Math.max(0, pact.slots - (e.sheet.spellcasting?.pact_slots_used ?? 0))
    rows.push({ label: 'Pact', level: Number(pact.level), max: pact.slots, left, pending })
  }
  return rows
}

function resources(e: Entry): (Pips & { note: string })[] {
  return (e.sheet.resources ?? []).map((r: any) => ({
    label: String(r.name),
    note: RECHARGE[r.recharge] ?? String(r.recharge ?? ''),
    max: r.max,
    left: Math.max(0, r.max - r.used),
    pending: false,
  }))
}

function conditions(e: Entry): string[] {
  const list = [...(e.sheet.conditions ?? [])].map(String)
  if (e.sheet.exhaustion > 0) list.push(`Exhaustion ${e.sheet.exhaustion}`)
  return list
}

/** Speeds other than walking: `swim 30`. Walking speed is the SPD stat. */
function otherSpeeds(s: any): string[] {
  const sp = s.speed ?? {}
  return ['swim', 'fly', 'climb', 'burrow'].filter((k) => typeof sp[k] === 'number').map((k) => `${k} ${sp[k]}`)
}

function hud(e: Entry): Hud {
  const d = e.derived ?? {}
  const p = e.derivedPending || !e.derived
  const hp = e.sheet.hp ?? {}
  const cs = casters(e)
  return {
    hp: { current: Number(hp.current ?? 0), max: Number(hp.max ?? 0), temp: Number(hp.temp ?? 0) },
    tiles: [
      { label: 'AC', value: String(e.sheet.ac?.value ?? '?') },
      { label: 'INIT', value: signed(d.initiative), pending: p },
      { label: 'SPD', value: String(e.sheet.speed?.walk ?? '?'), sub: otherSpeeds(e.sheet).join(' ') },
      ...cs.map((c) => ({ label: cs.length > 1 ? `${abbr(c.cls)} DC` : 'DC', value: c.dc, sub: `ATK ${c.attack}`, pending: p, accent: classAccent(c.cls) })),
    ],
    slots: slotRows(e).map((s) => ({ label: s.label, left: s.left, max: s.max, pending: s.pending })),
  }
}

/** The HUD in words, for a reader that cannot see it: every number on it. */
function hudAlt(e: Entry): string {
  const h = hud(e)
  const speeds = otherSpeeds(e.sheet)
  const cast = casters(e).map((c) => `${c.cls} spell save DC ${c.dc}, spell attack ${c.attack}`)
  const parts = [
    `HP ${h.hp.current} of ${h.hp.max}${h.hp.temp ? `, ${h.hp.temp} temporary` : ''}`,
    `AC ${h.tiles[0]?.value}, initiative ${h.tiles[1]?.value}, speed ${h.tiles[2]?.value}${speeds.length ? ` (${speeds.join(', ')})` : ''}`,
    ...(cast.length ? [cast.join('; ')] : []),
    ...(h.slots.length ? ['Slots ' + h.slots.map((s) => `${s.label} ${s.left}/${s.max}`).join(', ')] : []),
  ]
  return parts.join('. ') + '.' + (e.derivedPending ? ' Numbers marked ? may change on the next read.' : '')
}

/**
 * One quiet line: "Changed 13:20 · not re-read" after a write, "Read 13:19" on the
 * day it was read, "Last known · 3 Oct, 13:19" after that. It goes by when the
 * sheet was read, not by which session read it, so a module reload changes nothing.
 */
function freshness(e: Entry, now: number): string {
  const pend = e.derivedPending ? ' · numbers marked ? may change' : ''
  if (e.refreshing) return `Changed ${clock(e.seenAt)} · not re-read` + (e.last ? ' · ' + describeChange(e.last, e.sheet) : '') + pend
  return (sameDay(e.readAt, now) ? `Read ${clock(e.readAt)}` : `Last known · ${day(e.readAt)}`) + pend
}

/** The DM's rules that name this thing (a spell, a feature), by whole word. */
function rulesNaming(e: Entry, name: string): number {
  const re = new RegExp('\\b' + name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i')
  return (e.sheet.house_rules ?? []).filter((r: any) => re.test(String(r.rule ?? ''))).length
}
/** ★ marks a DM ruling, the same symbol as the header badge. */
const dmMark = (e: Entry, name: string) => (rulesNaming(e, name) ? ' ★' : '')

// ------------------------------------------------------------------ shared parts

const text = (el: Base, children: string, props: TextProps = {}) => el.Text({ ...props, children: [children] })
const row = (el: Base, children: RenderNode[], gap = 1) => el.Box({ flexDirection: 'row', columnGap: gap, children })
/** A column; `gap` rows between its children. The pane's one rhythm: a row between sections, none inside one. */
const col = (el: Base, children: RenderNode[], gap = 0) => el.Box({ flexDirection: 'column', ...(gap ? { rowGap: gap } : {}), children })
const md = (el: Base, lines: string[]) => el.Markdown({ text: lines.join('\n').slice(0, 10000) })
/** A section of a tab: its heading, then its lines, no space between. */
const section = (el: Base, head: RenderNode, lines: RenderNode[]) => col(el, [head, ...lines])

/**
 * What each kind of surface draws its ornaments with: the section headings
 * (a mark, the name, a slot level's pips and count, a rule), the action icons
 * and the concentration and ritual badges. Desktop paints them as Svg, the
 * terminal as Raster cells; the words are Text on both.
 */
interface Paint {
  /** Columns between an action's lead and its facts: two in the terminal, where dim is the only other cue. */
  gap: number
  /** `key` names a slot level's pips (`slots-1`). */
  head(label: string, mark: string, slots?: { left: number; max: number; pending: boolean } | null, key?: string): RenderNode
  icon(r: ActionRow): RenderNode
  badge(kind: 'conc' | 'ritual'): RenderNode
}

/** Does nothing: register.ts's `ui.press` hook acts on every press, with a fresh `$`. */
const NOOP = () => {}

/** Builds the pane's Buttons through the memo, so an unchanged Button is the same element as last time. */
function buttons(el: Base, memo: Map<string, RenderElement>) {
  const used = new Map<string, RenderElement>()
  const make = (props: Omit<ButtonProps, 'onPress'> & { key: string; label: string }): RenderElement => {
    const sig = JSON.stringify(props)
    const kept = used.get(sig) ?? memo.get(sig) ?? el.Button({ ...props, onPress: NOOP })
    used.set(sig, kept)
    return kept
  }
  const done = () => {
    memo.clear()
    for (const [k, v] of used) memo.set(k, v)
  }
  return { make, done }
}

/**
 * The tab buttons: short labels, a hotkey each. The open tab is marked by
 * more than colour. A plain Button draws the same whatever its variant (ButtonProps),
 * so Desktop gets real buttons with the open one `primary`, and the terminal gets
 * plain ones with `▸` before the open tab's label and the others dim.
 */
export function tabProps(surface: string, tab: TabId) {
  const terminal = surface === 'terminal'
  return TABS.map((t) => {
    const open = t.id === tab
    return {
      key: tabKey(t.id),
      label: terminal && open ? '▸' + t.label : t.label,
      hotkey: t.hotkey,
      ...(terminal ? { plain: true as const } : {}),
      ...(open ? (terminal ? {} : { variant: 'primary' as const }) : { dimColor: true }),
    }
  })
}

/**
 * The tab row, with real space between the buttons: one column on Desktop
 * (about 9 CSS px; the five buttons still fit one row at 38 columns), two in
 * the terminal, where plain buttons have no chrome to separate them (one row
 * from 53 columns; at 40, three and two).
 */
export const TAB_GAP = { remote: 1, terminal: 2 }
function tabRow(el: Base, v: PaneView, make: ReturnType<typeof buttons>['make']): RenderElement {
  return el.Box({ key: 'tabs', flexDirection: 'row', flexWrap: 'wrap', columnGap: v.surface === 'terminal' ? TAB_GAP.terminal : TAB_GAP.remote, rowGap: 0, children: tabProps(v.surface, v.tab).map(make) })
}

/** The DM-rules badge: the count, a press away from the Notes tab. */
function rulesBadge(e: Entry, make: ReturnType<typeof buttons>['make']): RenderElement | null {
  const n = (e.sheet.house_rules ?? []).length
  return n ? make({ key: RULES_KEY, label: `★ ${n} DM rule${n === 1 ? '' : 's'}`, hotkey: 'm', plain: true }) : null
}

/**
 * The second line of an action: the lead at full strength (a casting time that
 * is not an action, what to roll), then the facts dim. Two Texts in a wrapping
 * row with a column between, so a long facts run moves under the lead whole.
 */
function factsLine(el: Base, r: ActionRow, gap: number): RenderNode {
  const facts = r.facts.join(' · ')
  return el.Box({
    flexDirection: 'row',
    flexWrap: 'wrap',
    columnGap: gap,
    children: [...(r.lead ? [text(el, r.lead, { wrap: 'wrap' })] : []), ...(facts ? [text(el, facts, { dimColor: true, wrap: 'wrap' })] : [])],
  })
}

/**
 * One action, a row of the turn menu: the icon; the name (★ for a DM ruling,
 * the concentration and ritual badges) with the headline at the right edge
 * (dice and damage type, healing, or a casting time that is not an action);
 * under it the lead (what to roll, with the sheet's number), then the facts.
 * A weapon adds the rest of the sheet's own line, as written.
 */
function actionRow(el: Base, r: ActionRow, paint: Paint): RenderNode {
  const name = [
    text(el, r.name, { bold: true }),
    ...(r.dm ? [text(el, '★')] : []),
    ...(r.always ? [text(el, 'always', { dimColor: true })] : []),
    ...r.badges.map((b) => paint.badge(b)),
  ]
  const top = el.Box({
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    columnGap: 1,
    children: [el.Box({ flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', columnGap: 1, children: name }), ...(r.effect ? [text(el, r.effect, { bold: true })] : [])],
  })
  const lines: RenderNode[] = [top, factsLine(el, r, paint.gap)]
  if (r.written) lines.push(text(el, 'Sheet: ' + r.written, { dimColor: true, wrap: 'wrap' }))
  return el.Box({ key: 'action-' + r.key, flexDirection: 'row', columnGap: 1, alignItems: 'flex-start', children: [paint.icon(r), el.Box({ flexDirection: 'column', flexGrow: 1, flexShrink: 1, children: lines })] })
}

/** The DM's rules that name this thing (a spell, a weapon), as a test for ★. */
const dmNamed = (e: Entry) => (name: string) => rulesNaming(e, name) > 0

/**
 * Actions: the player's turn menu. Weapons, cantrips, each slot level (its
 * pips and count in the heading), other magic; one row per action, with the
 * snapshot's facts (actions.ts, facts.ts).
 */
function actionsTab(el: Base, e: Entry, paint: Paint): RenderNode[] {
  const slots = new Map(slotRows(e).map((s) => [s.level, { left: s.left, max: s.max, pending: s.pending }]))
  const MARK: Record<string, string> = { weapons: 'weapons', cantrips: 'cantrips', other: 'other' }
  const out = actionGroups(e, slots, dmNamed(e)).map((g) =>
    section(el, paint.head(g.label, MARK[g.id] ?? 'slots', g.slots, 'slots-' + g.id.replace('level-', '')), g.rows.map((r) => actionRow(el, r, paint))),
  )
  if (!out.length) out.push(text(el, 'No spells or weapons on this sheet.', { dimColor: true }))
  return out
}

function skillLines(e: Entry) {
  const d = e.derived ?? {}
  const prof = new Map<string, boolean>((e.sheet.proficiencies?.skills ?? []).map((k: any) => [String(k.name).toLowerCase(), !!k.expertise]))
  return Object.entries((d.skills ?? {}) as Record<string, number>)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, n]) => {
      const p = prof.get(name.toLowerCase())
      return { name, mark: p === undefined ? '' : p ? '◆' : '●', value: signed(n) + (e.derivedPending ? '?' : '') }
    })
}

/** Saves & skills: the six saves (proficiency marked), checks, skills, passive Perception, Hit Dice. */
function savesTab(el: Base, e: Entry, saves: RenderNode, paint: Paint): RenderNode[] {
  const d = e.derived ?? {}
  const s = e.sheet
  const pend = e.derivedPending ? '?' : ''
  const checks = el.Box({
    flexDirection: 'row',
    flexWrap: 'wrap',
    columnGap: 2,
    children: [
      text(el, 'Checks', { dimColor: true }),
      ...ABILITIES.map((a) => row(el, [text(el, a.toUpperCase(), { dimColor: true }), text(el, signed(d.modifiers?.[a]) + pend, { bold: true })])),
    ],
  })
  const skills = el.Box({
    flexDirection: 'row',
    flexWrap: 'wrap',
    children: skillLines(e).map((k) =>
      el.Box({
        width: '50%',
        flexDirection: 'row',
        justifyContent: 'space-between',
        paddingRight: 2,
        children: [text(el, k.name + (k.mark ? ' ' + k.mark : ''), k.mark ? {} : { dimColor: true }), text(el, k.value, { bold: true })],
      }),
    ),
  })
  const hd = Object.entries((d.hit_dice ?? {}) as Record<string, number>).map(([die, n]) => `${die} ${Math.max(0, n - (s.hit_dice_spent?.[die] ?? 0))}/${n}`)
  return [
    section(el, paint.head('Saving throws', 'saves'), [saves, checks]),
    section(el, paint.head('Skills', 'section'), [
      skills,
      text(el, `Passive Perception ${d.passive_perception ?? '?'}${pend}` + (hd.length ? ` · Hit Dice ${hd.join(', ')}` : ''), { wrap: 'wrap' }),
      text(el, '● proficient · ◆ expertise', { dimColor: true }),
    ]),
  ]
}

function featuresTab(el: Base, e: Entry, paint: Paint): RenderNode[] {
  const s = e.sheet
  const feat = (f: any) => `- **${f.name}**` + (f.from ? ` (${f.from})` : '') + (f.choice ? `: ${f.choice}` : '') + (f.note ? ` — ${f.note}` : '') + dmMark(e, f.name)
  const features = [...(s.feats ?? []).map((f: any) => feat({ ...f, from: f.from ?? 'feat' })), ...(s.features ?? []).map(feat)]
  const subclasses = (s.classes ?? []).filter((c: any) => c.subclass?.name).map((c: any) => `- **${c.subclass.name}** (${c.name} ${c.level})`)
  const pr = s.proficiencies ?? {}
  const prof = (
    [
      ['Armour', pr.armor],
      ['Weapons', pr.weapons],
      ['Tools', pr.tools],
      ['Languages', pr.languages],
    ] as [string, unknown][]
  )
    .filter(([, v]) => Array.isArray(v) && v.length)
    .map(([k, v]) => `- **${k}:** ${(v as string[]).join(', ')}`)
  return [
    ...(subclasses.length ? [section(el, paint.head('Subclasses', 'section'), [md(el, subclasses)])] : []),
    section(el, paint.head('Features', 'section'), [md(el, features.length ? features : ['_None._'])]),
    ...(prof.length ? [section(el, paint.head('Proficiencies', 'section'), [md(el, prof)])] : []),
  ]
}

function gearTab(el: Base, e: Entry, paint: Paint): RenderNode[] {
  const s = e.sheet
  const items = (s.inventory ?? []).map(
    (i: any) => `- ${i.name}` + (i.quantity !== 1 ? ` ×${i.quantity}` : '') + (i.attuned ? ' (attuned)' : '') + (i.note ? ` — ${i.note}` : ''),
  )
  const coins = Object.entries((s.currency ?? {}) as Record<string, number>)
    .filter(([, n]) => n > 0)
    .map(([k, n]) => `${n} ${k}`)
  return [section(el, paint.head('Inventory', 'section'), [md(el, items.length ? items : ['_Nothing written._'])]), text(el, `Money  ${coins.join(', ') || 'none'}`, { bold: true })]
}

/** Notes: the DM's rules first, then who the character is, with unresolved names flagged beside them. */
function notesTab(el: Base, e: Entry, paint: Paint): RenderNode[] {
  const s = e.sheet
  const out: RenderNode[] = []
  const rules = (s.house_rules ?? []).map((r: any) => `- ${r.rule}` + (r.by || r.date ? ` _(${[r.by, r.date].filter(Boolean).join(', ')})_` : ''))
  if (rules.length) out.push(section(el, paint.head('DM rules', 'rules'), [md(el, rules)]))
  const flag = (n: string) => (unresolvedName(n, e.unresolved) ? ' — _not in the rules snapshot_' : '')
  const who: string[] = []
  if (s.species?.name) who.push(`- **Species:** ${s.species.name}${flag(s.species.name)}` + (s.species.note ? ` — ${s.species.note}` : ''))
  if (s.background?.name) who.push(`- **Background:** ${s.background.name}${flag(s.background.name)}`)
  const named = [s.species?.name, s.background?.name].filter(Boolean) as string[]
  const otherUnresolved = e.unresolved.filter((u) => !named.some((n) => unresolvedName(n, [u])))
  if (otherUnresolved.length) who.push(`- **Not in the rules snapshot:** ${otherUnresolved.join(', ')}`)
  for (const [k, v] of Object.entries((s.details ?? {}) as Record<string, string>)) who.push(`- **${k.replace(/_/g, ' ')}:** ${v}`)
  if (who.length) out.push(section(el, paint.head('Character', 'section'), [md(el, who)]))
  if (s.notes) out.push(section(el, paint.head('Sheet notes', 'section'), [md(el, [String(s.notes)])]))
  if (!out.length) out.push(text(el, 'No notes on this sheet.', { dimColor: true }))
  return out
}

function tabBody(el: Base, e: Entry, v: PaneView, paint: Paint, saves: () => RenderNode): RenderNode[] {
  switch (v.tab) {
    case 'saves':
      return savesTab(el, e, saves(), paint)
    case 'features':
      return featuresTab(el, e, paint)
    case 'gear':
      return gearTab(el, e, paint)
    case 'notes':
      return notesTab(el, e, paint)
    default:
      return actionsTab(el, e, paint)
  }
}

const saveTiles = (e: Entry) => {
  const d = e.derived ?? {}
  const prof = new Set(e.sheet.proficiencies?.saves ?? [])
  return ABILITIES.map((a) => ({ label: a.toUpperCase(), value: signed(d.saving_throws?.[a]), proficient: prof.has(a), pending: e.derivedPending }))
}

// ------------------------------------------------------------------ the terminal

const withPacked = (r: { columns: number; rows: number; cells: Cell[] }) => ({ columns: r.columns, rows: r.rows, cells: packCells(r.cells) })
const themeOf = (colour: number) => (colour === C.green ? 'success' : colour === C.amber ? 'warning' : 'error')

function terminalPane(el: Elements['terminal'], e: Entry, v: PaneView): RenderElement {
  const width = Math.max(30, v.columns)
  const { make, done } = buttons(el, v.memo)
  const h = hud(e)
  const raster = (key: string, r: { columns: number; rows: number; cells: Cell[] }) => el.Raster({ key, ...withPacked(r) })
  let marks = 0
  const paint: Paint = {
    gap: 2,
    // `◆ 1st level ──────── █ █ █ 3/3`: the rule fills the row, a slot level's pips and count at its end.
    head(label, mark, slots, key) {
      const count = slots ? `${slots.left}/${slots.max}${slots.pending ? '?' : ''}` : ''
      const pipW = slots ? Math.min(17, Math.max(1, slots.max * 2 - 1)) : 0
      const used = 2 + label.length + 1 + (slots ? 1 + pipW + 1 + count.length : 0)
      return el.Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          raster('mark-' + marks++, markCells(mark)),
          text(el, label, { bold: true }),
          text(el, '─'.repeat(Math.max(2, width - used)), { dimColor: true }),
          ...(slots ? [raster(key ?? 'slots-' + marks, pipCells(slots.left, slots.max, C.slot, pipW)), text(el, count, slots.pending ? { color: 'warning' } : { bold: true })] : []),
        ],
      })
    },
    icon: (r) => raster('icon-' + r.key, iconCells(r.icon, r.cls ? classAccent(r.cls) : null)),
    badge: (kind) => text(el, kind === 'conc' ? 'conc' : 'ritual', { inverse: true }),
  }

  // Identity: name, level and classes on one line; the DM-rules badge; conditions only when present.
  const badge = rulesBadge(e, make)
  const conds = conditions(e)
  const identity = col(el, [
    el.Box({ flexDirection: 'row', flexWrap: 'wrap', columnGap: 2, children: [text(el, e.name, { bold: true }), text(el, identityLine(e), { dimColor: true })] }),
    ...(badge ? [badge] : []),
    ...(conds.length ? [text(el, '⚠ ' + conds.join(' · '), { color: 'warning', bold: true, wrap: 'wrap' })] : []),
  ])

  // Vitals: HP, the stats, a line per caster, then slots and resources as a table.
  const { current, max, temp } = h.hp
  const digits = `${current}/${max}`
  const tempText = temp ? `+${temp} temp` : ''
  const room = Math.max(10, width - 3 - digits.length - 2 - (tempText ? tempText.length + 1 : 0))
  const vitals: RenderNode[] = [
    row(el, [
      text(el, 'HP', { bold: true }),
      text(el, digits, { bold: true, color: themeOf(hpColour(current, max)) }),
      raster('hp', hpBarCells(current, max, temp, room)),
      ...(tempText ? [text(el, tempText, { color: 'cyan', bold: true })] : []),
    ]),
  ]
  const stat = (label: string, value: string, pending = false, extra = '') =>
    row(el, [text(el, label, { dimColor: true }), text(el, value + (pending ? '?' : ''), pending ? { color: 'warning' } : { bold: true }), ...(extra ? [text(el, extra, { dimColor: true })] : [])])
  const [ac, init, spd] = h.tiles
  vitals.push(
    el.Box({
      flexDirection: 'row',
      flexWrap: 'wrap',
      columnGap: 2,
      children: [stat('AC', ac?.value ?? '?'), stat('INIT', init?.value ?? '?', init?.pending), stat('SPD', spd?.value ?? '?', false, otherSpeeds(e.sheet).join(', '))],
    }),
  )
  const cs = casters(e)
  if (cs.length) {
    const p = e.derivedPending
    vitals.push(el.Box({ flexDirection: 'row', flexWrap: 'wrap', columnGap: 2, children: cs.map((c) => row(el, [text(el, c.cls, { dimColor: true }), stat('DC', c.dc, p), stat('atk', c.attack, p)])) }))
  }
  const table = [...h.slots.map((s) => ({ ...s, label: 'Slots ' + s.label, note: '', colour: C.slot })), ...resources(e).map((r) => ({ ...r, colour: C.gold }))]
  const labelW = Math.min(20, Math.max(9, ...table.map((r) => r.label.length)))
  const pipW = Math.min(17, Math.max(1, ...table.map((r) => r.max * 2 - 1)))
  table.forEach((r, i) =>
    vitals.push(
      el.Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [
          el.Box({ width: labelW, children: [text(el, r.label, { wrap: 'wrap' })] }),
          raster('pips-' + i, pipCells(r.left, r.max, r.colour, pipW)),
          text(el, `${r.left}/${r.max}` + (r.pending ? '?' : ''), r.pending ? { color: 'warning' } : { bold: true }),
          ...(r.note ? [text(el, r.note, { dimColor: true })] : []),
        ],
      }),
    ),
  )

  const saves = () =>
    el.Box({
      flexDirection: 'row',
      flexWrap: 'wrap',
      children: saveTiles(e).map((s) =>
        el.Box({
          width: 12,
          flexDirection: 'row',
          columnGap: 1,
          children: [text(el, s.label, s.proficient ? {} : { dimColor: true }), text(el, s.value + (s.pending ? '?' : ''), { bold: true }), ...(s.proficient ? [text(el, '●', { color: 'success' })] : [])],
        }),
      ),
    })
  const tree = col(
    el,
    [identity, col(el, vitals), tabRow(el, v, make), col(el, tabBody(el, e, v, paint, saves), 1), text(el, freshness(e, v.now), { dimColor: true, wrap: 'wrap' })],
    1,
  )
  done()
  return tree
}

// ------------------------------------------------------------------ desktop, editor, mobile

/** Every SVG is drawn at this many CSS px per art pixel, and given that size, so nothing rescales it. */
const SCALE = 2
/**
 * CSS px per `bodyColumns` column, measured on the Desktop Code tab (2.1.286,
 * 2026-10-04): the probe read 38 columns where the pane's content is about
 * 330–350 CSS px wide, so about 9. A remote surface counts `bodyColumns` as
 * the pane's width over its code font's advance (RenderViewport).
 */
export const PX_PER_COLUMN = 9

/**
 * The art width for this pane: its estimated slot over SCALE, one column short
 * so a slot at the low end of the estimate still holds it, at most ART_MAX
 * (328 CSS px at 38 columns and wider). A slot under ART_MIN's 296 px wraps the
 * stat tiles; ART_FLOOR (the six save tiles) is the least, 280 px, so from 32
 * columns the card is never wider than the slot. Always integer-scaled.
 */
export const artWidth = (columns: number) => Math.max(ART_FLOOR, Math.min(ART_MAX, Math.floor(((columns - 1) * PX_PER_COLUMN) / SCALE)))

function remotePane(el: Elements['desktop'], e: Entry, v: PaneView): RenderElement {
  const W = artWidth(v.columns)
  const { make, done } = buttons(el, v.memo)
  const svg = (alt: string, art: { source: string; width: number; height: number }) => el.Svg({ alt, source: art.source, width: art.width, height: art.height })

  const badge = rulesBadge(e, make)
  const conds = conditions(e)
  const identity = col(el, [
    el.Box({
      flexDirection: 'row',
      flexWrap: 'wrap',
      justifyContent: 'space-between',
      alignItems: 'center',
      children: [row(el, [text(el, e.name, { bold: true }), text(el, identityLine(e), { dimColor: true })]), ...(badge ? [badge] : [])],
    }),
    ...(conds.length ? [text(el, '⚠ ' + conds.join(' · '), { color: 'warning', bold: true, wrap: 'wrap' })] : []),
  ])
  const res = resources(e).map((r) =>
    el.Box({
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'center',
      children: [
        row(el, [text(el, r.label), ...(r.note ? [text(el, r.note, { dimColor: true })] : [])]),
        row(el, [svg(`${r.label}: ${r.left} of ${r.max} left`, pipsSvg(r.left, r.max, C.gold, SCALE)), text(el, `${r.left}/${r.max}`, { bold: true })]),
      ],
    }),
  )
  const paint: Paint = {
    gap: 1,
    // The mark and the name, a dotted rule across the rest of the row (clipped to it, so it ends
    // where the right-aligned numbers end), then a slot level's pips and count.
    head(label, mark, slots) {
      // Only the rule gives way: it starts at no width and takes what the row has left.
      const fixed = (children: RenderNode[]) => el.Box({ flexDirection: 'row', alignItems: 'center', columnGap: 1, flexShrink: 0, children })
      const rule = el.Box({ width: 0, flexGrow: 1, flexShrink: 1, overflow: 'hidden', children: [svg('', ruleSvg(W, SCALE))] })
      const end = slots ? [fixed([svg(`${slots.left} of ${slots.max} slots left`, pipsSvg(slots.left, slots.max, C.slot, SCALE)), text(el, `${slots.left}/${slots.max}${slots.pending ? '?' : ''}`, { bold: true })])] : []
      return el.Box({ flexDirection: 'row', alignItems: 'center', columnGap: 1, children: [fixed([svg('', markSvg(mark, SCALE)), text(el, label, { bold: true })]), rule, ...end] })
    },
    icon: (r) => svg(rowText(r), iconSvg(r.icon, r.cls ? classAccent(r.cls) : C.edge, SCALE)),
    badge: (kind) => svg(kind === 'conc' ? 'Concentration' : 'Ritual', badgeSvg(kind === 'conc' ? 'CONC' : 'RIT', SCALE)),
  }
  const saves = () => {
    const tiles = saveTiles(e)
    return svg('Saving throws: ' + tiles.map((s) => `${s.label} ${s.value}${s.proficient ? ' (proficient)' : ''}`).join(', '), savesSvg(tiles, SCALE, W))
  }
  const tree = col(
    el,
    [
      identity,
      svg(hudAlt(e), hudSvg(hud(e), SCALE, W)),
      ...(res.length ? [col(el, res)] : []),
      tabRow(el, v, make),
      col(el, tabBody(el, e, v, paint, saves), 1),
      text(el, freshness(e, v.now), { dimColor: true, wrap: 'wrap' }),
    ],
    1,
  )
  done()
  return tree
}

// ------------------------------------------------------------------ entry points

/** The pane: the HUD, the tab row, the open tab, and a freshness line when the data is not fresh. */
export function paneTree(el: Els, v: PaneView): RenderElement {
  const e = v.entry
  if (!e) {
    return col(el, [
      text(el, 'No sheet yet.', { bold: true }),
      text(el, 'Ask Claude to show your sheet. The pane fills in from its sheet_read result.', { dimColor: true, wrap: 'wrap' }),
    ])
  }
  // Branch on the surface, never on the table: Claude Code completes every
  // table with every element name, and Raster draws nothing off the terminal.
  if (v.surface === 'terminal') return terminalPane(el as Elements['terminal'], e, v)
  return remotePane(el as Elements['desktop'], e, v)
}

/** The band strip, while the pane is closed: name, a 10-cell HP bar, slot pips, the key hint. */
export function bandTree(el: Els, e: Entry): RenderElement {
  const hp = e.sheet.hp ?? { current: 0, max: 1, temp: 0 }
  const frac = hp.max > 0 ? hp.current / hp.max : 0
  const filled = Math.max(0, Math.min(10, Math.round(frac * 10)))
  const slots = slotRows(e)
  const kids: RenderNode[] = [
    text(el, e.name, { bold: true }),
    row(el, [text(el, '█'.repeat(filled), { color: themeOf(hpColour(hp.current, hp.max)) }), text(el, '░'.repeat(10 - filled), { dimColor: true })], 0),
    text(el, `${hp.current}/${hp.max}` + (hp.temp ? ` +${hp.temp}` : '')),
  ]
  if (slots.length) {
    const left = slots.reduce((n, s) => n + s.left, 0)
    const max = slots.reduce((n, s) => n + s.max, 0)
    kids.push(row(el, [text(el, '◆'.repeat(left), { color: 'magenta' }), text(el, '◇'.repeat(max - left), { dimColor: true })], 0))
  }
  kids.push(text(el, '/sheet', { dimColor: true }))
  return row(el, kids)
}

files.hooks/actions.ts:
// The Actions tab as a player's turn menu: the sheet's weapons and spells,
// each looked up in the generated facts table (facts.ts, the rules server's
// own snapshot) and worded the way a 2024 player reads them. Pure: no mods
// API. Nothing here computes a rule:
// - the facts are the snapshot's, copied by facts/build.py;
// - the attack bonus and save DC are the sheet's `derived` numbers for the
//   class the spell is listed under, and a weapon's bonus is the sheet's own
//   written one;
// - a cantrip's die is a lookup in the data's own scaling table at
//   `derived.total_level`.
// A name with no record is shown as the sheet writes it and flagged, never guessed.

import type { Entry } from './sheet.ts'
import { SPELL_ALIASES, SPELLS, WEAPONS, type SpellRow, type WeaponRow } from './facts.ts'

/** What an action's icon shows, most specific first: damage type, healing, reaction, save, attack, school. */
export type IconId =
  | 'fire' | 'lightning' | 'thunder' | 'cold' | 'acid' | 'poison' | 'force' | 'necrotic' | 'radiant' | 'psychic'
  | 'bludgeoning' | 'piercing' | 'slashing' | 'multi' | 'heal' | 'reaction' | 'save' | 'attack'
  | 'abjuration' | 'conjuration' | 'divination' | 'enchantment' | 'evocation' | 'illusion' | 'necromancy' | 'transmutation'
  | 'unknown'

export const DAMAGE_ICONS = ['fire', 'lightning', 'thunder', 'cold', 'acid', 'poison', 'force', 'necrotic', 'radiant', 'psychic', 'bludgeoning', 'piercing', 'slashing'] as const
const SCHOOL: Record<string, IconId> = {
  A: 'abjuration', C: 'conjuration', D: 'divination', E: 'enchantment', V: 'evocation', I: 'illusion', N: 'necromancy', T: 'transmutation',
}

export interface ActionRow {
  key: string
  /** As the sheet writes it. */
  name: string
  icon: IconId
  /** The class the spell is listed under (its accent and its numbers); '' for weapons and other magic. */
  cls: string
  /** A DM rule names it: ★. */
  dm: boolean
  /** Always prepared (a domain or subclass spell). */
  always: boolean
  /** The headline: dice and damage type, healing, or the casting time when it is not an action. */
  effect: string
  /**
   * What the turn needs first, at full strength: a casting time that is not an
   * action (a bonus action or reaction is another part of the turn), then what
   * to roll with the sheet's number: `ATK +5`, `CON save DC 11`, `ATK +2 (as written)`.
   */
  lead: string
  /** The rest, dim: casting time, range, duration, components; or a weapon's properties. */
  facts: string[]
  badges: ('conc' | 'ritual')[]
  /** The rest of the sheet's own line for a weapon, after its bonus ("1d8 bludgeoning"), shown as written. */
  written: string
  /** No record in the snapshot: shown plainly and flagged. */
  missing: boolean
  /** The book the record came from (`XPHB`), for the alt text. */
  source: string
}

export interface ActionGroup {
  id: string
  label: string
  /** A slot level's pips: left and max. */
  slots: { left: number; max: number; pending: boolean } | null
  rows: ActionRow[]
}

// ------------------------------------------------------------------ lookup

/** The server's name normalisation (`norm`): lower case, every run of other characters one space. */
export const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()

/** Sources by name, for the name-only fallback. */
function index(table: Record<string, unknown>): Map<string, string[]> {
  const out = new Map<string, string[]>()
  for (const k of Object.keys(table)) {
    const at = k.lastIndexOf('|')
    const name = k.slice(0, at)
    out.set(name, [...(out.get(name) ?? []), k.slice(at + 1)])
  }
  return out
}
const SPELL_NAMES = index(SPELLS)
const WEAPON_NAMES = index(WEAPONS)

/** A 2024 sheet (or one that does not say) prefers the 2024 books; a 2014 sheet the 2014 ones. */
const PREFER_2024 = ['xphb', 'efa', 'xdmg', 'phb', 'xge', 'tce', 'eepc', 'dmg', 'toa']
const PREFER_2014 = ['phb', 'xge', 'tce', 'eepc', 'dmg', 'toa', 'xphb', 'efa', 'xdmg']
const rank = (order: string[], s: string) => {
  const i = order.indexOf(s)
  return i < 0 ? order.length : i
}

function find<R>(table: Record<string, R>, names: Map<string, string[]>, wanted: string[], source: string | undefined, ruleset: unknown): { row: R; source: string } | null {
  for (const n of wanted) {
    if (source) {
      const row = table[n + '|' + source.toLowerCase()]
      if (row) return { row, source: source.toUpperCase() }
    }
  }
  const order = ruleset === '2014' ? PREFER_2014 : PREFER_2024
  for (const n of wanted) {
    const sources = [...(names.get(n) ?? [])].sort((a, b) => rank(order, a) - rank(order, b))
    const s = sources[0]
    const row = s ? table[n + '|' + s] : undefined
    if (s && row) return { row, source: s.toUpperCase() }
  }
  return null
}

/** A spell by its own name and source; else by name, the edition's books first; else null. */
export function spellFact(name: string, source?: string, ruleset?: unknown): { row: SpellRow; source: string } | null {
  const n = norm(name)
  const alias = SPELL_ALIASES[n]
  return find(SPELLS, SPELL_NAMES, alias ? [n, alias] : [n], source, ruleset)
}

/** A weapon by its own name and source, then by name; a plural ("Daggers") also tries the singular. */
export function weaponFact(name: string, source?: string, ruleset?: unknown): { row: WeaponRow; source: string } | null {
  const n = norm(name)
  const wanted = [n, ...(n.endsWith('s') ? [n.slice(0, -1)] : [])]
  return find(WEAPONS, WEAPON_NAMES, wanted, source, ruleset)
}

/** A cantrip's dice at this character level, from the data's table ("1:1d10 5:2d10 …"), or ''. */
export function cantripDice(table: string, level: number | null): string {
  if (!table.includes(':')) return table
  if (level === null) return ''
  let out = ''
  for (const pair of table.split(' ')) {
    const [lv, dice] = pair.split(':')
    if (Number(lv) <= level) out = dice ?? ''
  }
  return out
}

// ------------------------------------------------------------------ wording

const ORDINAL = (l: number) => ({ 1: '1st', 2: '2nd', 3: '3rd' })[l] ?? l + 'th'
const COMPONENTS = (c: string) => [...c].join(', ')
const signed = (n: unknown) => (typeof n === 'number' ? (n >= 0 ? '+' + n : String(n)) : typeof n === 'string' ? n : '?')

/** `1d10 fire`, `5d6 fire/radiant`, `3d8 · 6 types`, `force`. */
function damageText(dice: string, types: string[]): string {
  const t = types.length > 2 ? `${types.length} types` : types.join('/')
  return dice ? (types.length > 2 ? `${dice} · ${t}` : `${dice} ${t}`) : t
}

function spellIcon(row: SpellRow): IconId {
  const [, school, time, , , , flags, damage, save] = row
  const types = damage ? damage.split(',') : []
  if (types.length > 2) return 'multi'
  const first = types[0]
  if (first && (DAMAGE_ICONS as readonly string[]).includes(first)) return first as IconId
  const f = flags.split(' ')
  if (f.includes('heal')) return 'heal'
  if (time.includes('Reaction')) return 'reaction'
  if (save) return 'save'
  if (f.includes('melee') || f.includes('ranged')) return 'attack'
  return SCHOOL[school] ?? 'unknown'
}

interface Caster {
  dc: string
  attack: string
}

/** One spell row: the facts as a 2024 player reads them, the roll with the class's own number. */
export function spellRow(key: string, name: string, source: string | undefined, e: Entry, opts: { cls: string; caster: Caster | null; dm: boolean; always: boolean; otherLevel?: boolean }): ActionRow {
  const hit = spellFact(name, source, e.sheet.ruleset)
  const base = { key, name, cls: opts.cls, dm: opts.dm, always: opts.always, written: '', badges: [] as ActionRow['badges'] }
  if (!hit) return { ...base, icon: 'unknown', effect: '', lead: '', facts: ['Not in the rules snapshot'], missing: true, source: source ?? '' }
  const [level, , time, range, comps, duration, flagText, damage, save, diceText] = hit.row
  const flags = flagText ? flagText.split(' ') : []
  const types = damage ? damage.split(',') : []
  const total = typeof e.derived?.total_level === 'number' ? e.derived.total_level : null
  const dice = level === 0 ? cantripDice(diceText, total) : diceText
  const pend = e.derivedPending ? '?' : ''
  let effect = types.length ? damageText(dice, types) : flags.includes('heal') && dice ? `heal ${dice}${flags.includes('mod') ? ' + mod' : ''}` : ''
  if (!effect && time !== 'Action') effect = time
  const attack = flags.includes('melee') ? 'Melee' : flags.includes('ranged') ? 'Ranged' : ''
  const roll = attack
    ? `${attack} ATK${opts.caster ? ' ' + opts.caster.attack + pend : ''}`
    : save
      ? `${save} save${opts.caster ? ' DC ' + opts.caster.dc + pend : ''}`
      : ''
  const lead = [...(time !== 'Action' && effect !== time ? [time] : []), ...(roll ? [roll] : [])].join(' · ')
  const facts = [
    ...(opts.otherLevel ? [level === 0 ? 'Cantrip' : ORDINAL(level)] : []),
    ...(time === 'Action' ? [time] : []),
    range,
    ...(duration && duration !== 'Instant' ? [duration] : []),
    COMPONENTS(comps),
  ].filter(Boolean)
  const badges: ActionRow['badges'] = [...(flags.includes('conc') ? ['conc' as const] : []), ...(flags.includes('ritual') ? ['ritual' as const] : [])]
  return { ...base, icon: spellIcon(hit.row), effect, lead, facts, badges, missing: false, source: hit.source }
}

/**
 * A weapon line as a player reads it: "+2 · 1d8 bludgeoning". The transcription
 * writes "attack written +2, 1d8 bludgeoning; …"; only that prefix is taken off,
 * the rest follows after a ·. Anything else is shown as written. No bonus is computed.
 */
export function weaponLine(note: string): string {
  const m = /^attack written ([+-]\d+), (.+)$/.exec(note.trim())
  return m ? [m[1], ...(m[2] ?? '').split('; ')].join(' · ') : note
}

/**
 * Weapon Mastery (a 2024 class feature). Its `choice`, when written, names the
 * weapons it covers ("Longsword, Handaxe"); without one, every weapon's
 * mastery property is shown.
 */
function mastery(e: Entry): { all: boolean; names: string[] } | null {
  const f = [...(e.sheet.features ?? []), ...(e.sheet.feats ?? [])].find((x: any) => norm(String(x.name ?? '')) === 'weapon mastery')
  if (!f) return null
  const names = typeof f.choice === 'string' ? f.choice.split(/,|;|\band\b/).map(norm).filter(Boolean) : []
  return { all: !names.length, names }
}
const singular = (n: string) => (n.endsWith('s') ? n.slice(0, -1) : n)

/** The weapon's data line: `Melee · Versatile 1d8 · Topple`, mastery only with Weapon Mastery. */
export function weaponFacts(row: WeaponRow, withMastery: boolean): string[] {
  const [, kind, , , versatile, props, range, masteryName] = row
  const words = (props ? props.split(',') : []).map((p) =>
    p === 'Versatile' && versatile ? `Versatile ${versatile}` : (p === 'Thrown' || p === 'Ammunition') && range ? `${p} ${range}` : p,
  )
  return [kind === 'ranged' ? 'Ranged' : 'Melee', ...words, ...(withMastery && masteryName ? [masteryName] : [])]
}

function weaponRows(e: Entry, dmNames: (name: string) => boolean): ActionRow[] {
  const wm = mastery(e)
  const out: ActionRow[] = []
  ;(e.sheet.inventory ?? []).forEach((i: any, n: number) => {
    const name = String(i.name ?? '')
    const note = String(i.note ?? '')
    const hit = weaponFact(name, i.source, e.sheet.ruleset)
    const writtenAttack = /^attack written /i.test(note.trim())
    if (!hit && !writtenAttack) return
    // The written bonus is the roll, labelled as written; the rest of the sheet's line follows the facts.
    const parts = note ? weaponLine(note).split(' · ') : []
    const lead = writtenAttack ? `ATK ${parts[0]} (as written)` : ''
    const written = (writtenAttack ? parts.slice(1) : parts).join(' · ')
    const base = { key: 'weapon-' + n, name, cls: '', dm: dmNames(name), always: false, lead, written, badges: [] as ActionRow['badges'] }
    if (!hit) {
      out.push({ ...base, icon: 'unknown', effect: '', facts: ['Not in the rules snapshot'], missing: true, source: String(i.source ?? '') })
      return
    }
    const [, , dice, type] = hit.row
    const covered = !!wm && (wm.all || wm.names.some((w) => singular(w) === singular(norm(name))))
    const icon: IconId = (DAMAGE_ICONS as readonly string[]).includes(type) ? (type as IconId) : 'unknown'
    out.push({ ...base, icon, effect: [dice, type].filter(Boolean).join(' '), facts: weaponFacts(hit.row, covered), missing: false, source: hit.source })
  })
  return out
}

/**
 * The turn menu: Weapons, Cantrips, then each slot level (its pips in the
 * heading), then Other magic (spells from species, feats or items, and any
 * spell whose level neither the sheet nor the snapshot gives).
 */
export function actionGroups(e: Entry, slots: Map<number, { left: number; max: number; pending: boolean }>, dmNames: (name: string) => boolean): ActionGroup[] {
  const groups: ActionGroup[] = []
  const weapons = weaponRows(e, dmNames)
  if (weapons.length) groups.push({ id: 'weapons', label: 'Weapons', slots: null, rows: weapons })
  const casters = new Map<string, Caster>(((e.derived?.spellcasting ?? []) as any[]).map((c) => [String(c.class), { dc: String(c.save_dc ?? '?'), attack: signed(c.attack) }]))
  const byLevel = new Map<number, ActionRow[]>()
  const other: ActionRow[] = []
  for (const sc of e.sheet.spellcasting?.by_class ?? []) {
    const cls = String(sc.class ?? '')
    const caster = casters.get(cls) ?? null
    const add = (lvl: number | null, row: ActionRow) => {
      if (lvl === null) other.push(row)
      else byLevel.set(lvl, [...(byLevel.get(lvl) ?? []), row])
    }
    ;(sc.cantrips ?? []).forEach((c: any, i: number) => add(0, spellRow(`spell-${cls}-c${i}`, c.name, c.source, e, { cls, caster, dm: dmNames(c.name), always: false })))
    ;(sc.spells ?? []).forEach((sp: any, i: number) => {
      const level = typeof sp.level === 'number' ? sp.level : spellFact(sp.name, sp.source, e.sheet.ruleset)?.row[0] ?? null
      add(level, spellRow(`spell-${cls}-${i}`, sp.name, sp.source, e, { cls, caster, dm: dmNames(sp.name), always: !!sp.always, otherLevel: level === null }))
    })
  }
  for (const [lvl, rows] of [...byLevel].sort(([a], [b]) => a - b)) {
    groups.push({ id: lvl === 0 ? 'cantrips' : 'level-' + lvl, label: lvl === 0 ? 'Cantrips' : `${ORDINAL(lvl)} level`, slots: lvl === 0 ? null : slots.get(lvl) ?? null, rows })
  }
  ;(e.sheet.spellcasting?.other ?? []).forEach((x: any, i: number) => other.push(spellRow('other-' + i, x.name, x.source, e, { cls: '', caster: null, dm: dmNames(x.name), always: false, otherLevel: true })))
  if (other.length) groups.push({ id: 'other', label: 'Other magic', slots: null, rows: other })
  return groups
}

/** A row in words, for the icon's alt text: `Fire Bolt: 1d10 fire. Ranged ATK +5 · Action · 120 ft · V, S.` */
export function rowText(r: ActionRow): string {
  const head = r.name + (r.dm ? ' ★' : '') + (r.effect ? ': ' + r.effect : '')
  const line = [r.lead, ...r.facts, ...r.badges.map((b) => (b === 'conc' ? 'Concentration' : 'Ritual'))].filter(Boolean).join(' · ')
  return head + '. ' + line + '.' + (r.written ? ` Sheet: ${r.written}.` : '')
}

files.hooks/art.ts:
// Pixel art: one palette, a 3×5 font for numerals and short labels, the
// Desktop HUD and saves strip as SVG, inline pips, and the terminal's
// half-block cells (packed as the Raster element takes them). Words are never
// drawn here: view.ts sets them as Text. Pure functions: no mods API, and
// nothing reads a sheet; view.ts hands in the facts already worded.

/** Twelve colours, the brief's ceiling. Each SVG draws its own panel, so it reads on light and dark. */
export const C = {
  panel: 0x161a23,
  inset: 0x242a38,
  edge: 0x3b4256,
  ink: 0xeceae3,
  dim: 0x8a90a2,
  green: 0x4cc552,
  amber: 0xf0a020,
  red: 0xe5484d,
  temp: 0x3fc8e0,
  empty: 0x394052,
  slot: 0xa07cff,
  gold: 0xf2c14e,
} as const

/** The Raster element's "terminal default" colour. */
export const DEFAULT = 0x01000000

const hex = (c: number) => '#' + c.toString(16).padStart(6, '0')

// ------------------------------------------------------------------ font

/** 3×5 glyphs, five rows of three bits (WIDE has the few that need more). Unknown characters draw as '?'. */
const GLYPHS: Record<string, string> = {
  '0': '111101101101111', '1': '010110010010111', '2': '111001111100111', '3': '111001111001111',
  '4': '101101111001001', '5': '111100111001111', '6': '111100111101111', '7': '111001001010010',
  '8': '111101111101111', '9': '111101111001111', '/': '001001010100100', '+': '000010111010000',
  '-': '000000111000000', ':': '000010000010000', '.': '000000000000010', ' ': '000000000000000',
  '?': '111001011000010', '·': '000000010000000', ',': '000000000010100', "'": '010010000000000',
  '(': '010100100100010', ')': '010001001001010', '!': '010010010000010', '×': '000101010101000',
  '…': '000000000000101', '=': '000111000111000', '_': '000000000000111',
  A: '010101111101101', B: '110101110101110', C: '011100100100011', D: '110101101101110',
  E: '111100110100111', F: '111100110100100', G: '011100101101011', H: '101101111101101',
  I: '111010010010111', J: '001001001101010', K: '101101110101101', L: '100100100100111',
  M: '101111111101101', N: '110101101101101', O: '010101101101010', P: '110101110100100',
  Q: '010101101110011', R: '110101110101101', S: '011100010001110', T: '111010010010010',
  U: '101101101101111', V: '101101101101010', W: '101101111111101', X: '101101010101101',
  Y: '101101010010010', Z: '111001010100111',
}
/** M, N and W are illegible three pixels wide; these rows are wider. */
const WIDE: Record<string, string[]> = {
  M: ['10001', '11011', '10101', '10001', '10001'],
  N: ['1001', '1101', '1011', '1001', '1001'],
  W: ['10001', '10001', '10101', '11011', '10001'],
}

interface Glyph {
  w: number
  rows: string[]
}
const glyph = (ch: string): Glyph => {
  const wide = WIDE[ch]
  if (wide) return { w: wide[0]?.length ?? 3, rows: wide }
  const bits = GLYPHS[ch] ?? GLYPHS['?'] ?? ''
  return { w: 3, rows: [0, 1, 2, 3, 4].map((r) => bits.slice(r * 3, r * 3 + 3)) }
}

/** What the font can draw: capitals, accents dropped, curly quotes and dashes straightened. */
export function fontText(s: string): string {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[‘’]/g, "'")
    .replace(/[–—]/g, '-')
    .toUpperCase()
}

/** Width in art pixels of `text` (in font form) at `scale`: each glyph's width, one pixel between. */
export const textWidth = (text: string, scale = 1) => {
  const chars = [...text]
  return (chars.length ? chars.reduce((n, ch) => n + glyph(ch).w + 1, 0) - 1 : 0) * scale
}

// ------------------------------------------------------------------ svg painter

/**
 * Rectangles on an integer grid, kept in paint order and merged into one
 * `<path>` per run of a colour: far smaller than a `<rect>` per pixel run.
 */
function painter() {
  const layers: { c: number; d: string }[] = []
  const rect = (x: number, y: number, w: number, h: number, c: number) => {
    if (w <= 0 || h <= 0) return
    const d = `M${x} ${y}h${w}v${h}h${-w}z`
    const top = layers[layers.length - 1]
    if (top && top.c === c) top.d += d
    else layers.push({ c, d })
  }
  /** Draws `s` (already in font form) and returns its width. */
  const text = (s: string, x: number, y: number, scale: number, c: number) => {
    let gx = 0
    for (const ch of s) {
      const g = glyph(ch)
      g.rows.forEach((bits, row) => {
        let col = 0
        while (col < g.w) {
          if (bits[col] !== '1') {
            col++
            continue
          }
          let end = col
          while (end < g.w && bits[end] === '1') end++
          rect(x + (gx + col) * scale, y + row * scale, (end - col) * scale, scale, c)
          col = end
        }
      })
      gx += g.w + 1
    }
    return textWidth(s, scale)
  }
  /** A shape with its corners cut one pixel per step, `steps` deep. */
  const stepped = (x: number, y: number, w: number, h: number, c: number, steps = 2) => {
    for (let i = 0; i <= steps; i++) rect(x + steps - i, y + i, w - 2 * (steps - i), h - 2 * i, c)
  }
  /** A stepped frame `t` pixels thick around a stepped fill. */
  const framed = (x: number, y: number, w: number, h: number, t: number, edge: number, fill: number) => {
    stepped(x, y, w, h, edge, 2)
    stepped(x + t, y + t, w - 2 * t, h - 2 * t, fill, 1)
  }
  const svg = (w: number, h: number, scale: number, under: typeof layers = []) =>
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" width="${w * scale}" height="${h * scale}" shape-rendering="crispEdges">` +
    [...under, ...layers].map((l) => `<path fill="${hex(l.c)}" d="${l.d}"/>`).join('') +
    '</svg>'
  return { rect, text, stepped, framed, svg, layers }
}

/** The colour HP is drawn in: green above half, amber, red below a quarter. */
export const hpColour = (current: number, max: number) => {
  const frac = max > 0 ? current / max : 0
  return frac > 0.5 ? C.green : frac >= 0.25 ? C.amber : C.red
}

/**
 * Segments for current/max plus temp: one per hit point while they fit, else
 * each segment stands for several. Spent segments `empty`; temp HP as cyan
 * segments after the maximum.
 */
export function hpSegments(current: number, max: number, temp: number, room: number, empty: number): number[] {
  const total = Math.max(1, max) + Math.max(0, temp)
  const per = Math.max(1, Math.ceil(total / Math.max(1, room)))
  const n = Math.ceil(total / per)
  const fill = hpColour(current, max)
  const maxSegs = Math.ceil(Math.max(1, max) / per)
  const full = Math.min(Math.ceil(Math.max(0, current) / per), maxSegs)
  const out: number[] = []
  for (let i = 0; i < n; i++) out.push(i < full ? fill : i < maxSegs ? empty : C.temp)
  return out
}

// ------------------------------------------------------------------ the Desktop HUD

/** One stat tile: a short label over a value, an optional small line under it. */
export interface HudTile {
  label: string
  value: string
  sub?: string
  /** A derived number the last write may change: drawn dim, with an amber '?'. */
  pending?: boolean
  /** The label's colour: a caster's class accent (the frame of that class's spell icons). */
  accent?: number
}

/** One row of slot pips: `1ST`, `PACT`. */
export interface HudSlots {
  label: string
  left: number
  max: number
  pending?: boolean
}

export interface Hud {
  hp: { current: number; max: number; temp: number }
  tiles: HudTile[]
  slots: HudSlots[]
}

/**
 * The art width range in art pixels. Each SVG is drawn at an integer scale
 * with an explicit size, so nothing rescales it; view.ts picks the width.
 * 148 is the narrowest that keeps five stat tiles on one row (a narrower card
 * wraps them); 140 is the narrowest the six save tiles fit; 164 is the widest
 * (328 CSS px, under the 330 px low end of the measured 38-column pane).
 */
export const ART_FLOOR = 140
export const ART_MIN = 148
export const ART_MAX = 164

const PAD = 5
/** The space between the HP row, the tiles and the slots: one rhythm. */
const GAP = 5
const PIP = 7
const PIP_STEP = 9
const MAX_PIPS = 9

const PIP_FULL = ['...#...', '..###..', '.#####.', '#######', '.#####.', '..###..', '...#...']
const PIP_SPENT = ['...#...', '..#.#..', '.#...#.', '#.....#', '.#...#.', '..#.#..', '...#...']
const HEART = ['.##...##.', '####.####', '#########', '#########', '.#######.', '..#####..', '...###...', '....#....']

type Painter = ReturnType<typeof painter>
const bitmap = (p: Painter, art: string[], x: number, y: number, c: number) =>
  art.forEach((row, dy) => [...row].forEach((ch, dx) => ch === '#' && p.rect(x + dx, y + dy, 1, 1, c)))

/** The panel every SVG sits on, then the content over it; width and height in CSS px at `scale`. */
function framedSvg(p: Painter, w: number, h: number, scale: number) {
  const bg = painter()
  bg.framed(0, 0, w, h, 2, C.edge, C.panel)
  return { source: p.svg(w, h, scale, bg.layers), width: w * scale, height: h * scale }
}

/** Tile widths: each its content plus padding, the slack shared out. */
function tileWidths(needs: number[], room: number, gap: number): number[] {
  const slack = room - needs.reduce((a, b) => a + b, 0) - gap * (needs.length - 1)
  const each = Math.floor(Math.max(0, slack) / needs.length)
  const ws = needs.map((n) => n + each)
  if (slack > 0 && ws.length) ws[ws.length - 1] = (ws[ws.length - 1] ?? 0) + (slack - each * needs.length)
  return ws
}

/**
 * What a player checks between turns, as one strip: HP (big current, small
 * maximum, the segmented bar, temp in cyan), the stat tiles, then one row of
 * pips per slot level with the count at the right edge.
 */
export function hudSvg(h: Hud, scale: number, W: number): { source: string; width: number; height: number } {
  const inner = W - 2 * PAD
  const p = painter()
  let y = PAD

  // HP: heart, big current, small maximum, temp; the bar takes the rest of the row.
  const { current, max, temp } = h.hp
  bitmap(p, HEART, PAD + 1, y + 4, C.red)
  let x = PAD + 13
  x += p.text(String(current), x, y, 3, C.ink) + 2
  x += p.text('/' + max, x, y + 5, 2, C.dim)
  if (temp > 0) x += 4 + p.text('+' + temp, x + 4, y + 5, 2, C.temp)
  let barX = x + 5
  let barY = y + 3
  let bottom = y + 15
  if (W - PAD - barX < 40) {
    // No room beside the digits: the bar goes under them, full width.
    barX = PAD
    barY = y + 20
    bottom = barY + 9
  }
  const barW = W - PAD - barX
  p.stepped(barX, barY, barW, 9, C.inset, 1)
  const segs = hpSegments(current, max, temp, Math.floor((barW - 4 + 1) / 3), C.empty)
  const step = Math.max(2, Math.floor((barW - 4 + 1) / segs.length))
  const sx = barX + 2 + Math.floor((barW - 4 - (segs.length * step - 1)) / 2)
  segs.forEach((c, i) => p.rect(sx + i * step, barY + 2, step - 1, 5, c))
  y = bottom + GAP

  // The stat tiles, sized to their content; a second row when they do not fit one.
  if (h.tiles.length) {
    const gap = 2
    const words = h.tiles.map((t) => ({ label: fontText(t.label), value: fontText(t.value), sub: fontText(t.sub ?? ''), pending: t.pending === true, accent: t.accent ?? C.dim }))
    const needs = words.map((t) => Math.max(textWidth(t.label), textWidth(t.value, 2), textWidth(t.sub)) + 4)
    const rows: number[][] = [[]]
    let used = 0
    needs.forEach((n, i) => {
      const last = rows[rows.length - 1] ?? []
      if (last.length && used + gap + n > inner) {
        rows.push([i])
        used = n
      } else {
        last.push(i)
        used += (last.length > 1 ? gap : 0) + n
      }
    })
    for (const r of rows) {
      const ws = tileWidths(r.map((i) => needs[i] ?? 0), inner, gap)
      const tileH = r.some((i) => words[i]?.sub) ? 30 : 23
      let tx = PAD
      r.forEach((i, j) => {
        const t = words[i]
        const w = ws[j] ?? 0
        if (!t) return
        p.stepped(tx, y, w, tileH, C.inset, 2)
        p.text(t.label, tx + Math.floor((w - textWidth(t.label)) / 2), y + 3, 1, t.accent)
        p.text(t.value, tx + Math.floor((w - textWidth(t.value, 2)) / 2), y + 10, 2, t.pending ? C.dim : C.ink)
        if (t.pending) p.text('?', tx + w - 5, y + 2, 1, C.amber)
        if (t.sub) p.text(t.sub, tx + Math.floor((w - textWidth(t.sub)) / 2), y + 22, 1, C.dim)
        tx += w + gap
      })
      bottom = y + tileH
      y = bottom + gap
    }
    y = bottom + GAP
  }

  // Slots: label, pips, count at the right edge.
  if (h.slots.length) {
    const labels = h.slots.map((s) => fontText(s.label))
    const labelW = Math.max(...labels.map((l) => textWidth(l)))
    h.slots.forEach((s, i) => {
      p.text(labels[i] ?? '', PAD, y + 1, 1, C.dim)
      pips(p, s.left, s.max, C.slot, PAD + labelW + 6, y)
      const count = `${s.left}/${s.max}`
      p.text(count, W - PAD - textWidth(count) - (s.pending ? 4 : 0), y + 1, 1, s.pending ? C.dim : C.ink)
      if (s.pending) p.text('?', W - PAD - 3, y + 1, 1, C.amber)
      bottom = y + PIP
      y = bottom + 3
    })
  }
  return framedSvg(p, W, bottom + PAD, scale)
}

/** Diamond pips at (x, y): filled for each left, outlined for each spent; past MAX_PIPS a meter. */
function pips(p: Painter, left: number, max: number, colour: number, x: number, y: number): number {
  if (max <= MAX_PIPS) {
    for (let i = 0; i < max; i++) bitmap(p, i < left ? PIP_FULL : PIP_SPENT, x + i * PIP_STEP, y, i < left ? colour : C.dim)
    return Math.max(0, max * PIP_STEP - 2)
  }
  const w = MAX_PIPS * PIP_STEP - 2
  p.stepped(x, y, w, PIP, C.inset, 1)
  p.rect(x + 1, y + 1, Math.round(((w - 2) * left) / Math.max(1, max)), PIP - 2, colour)
  return w
}

/** One save: the ability's three letters, the bonus, whether proficient. */
export interface SaveTile {
  label: string
  value: string
  proficient: boolean
  pending?: boolean
}

/** The six saves as one strip of tiles; a proficient one has a green stepped outline and a bright label. */
export function savesSvg(saves: SaveTile[], scale: number, W: number): { source: string; width: number; height: number } {
  const p = painter()
  const gap = 2
  const words = saves.map((s) => ({ label: fontText(s.label), value: fontText(s.value) }))
  const ws = tileWidths(words.map((t) => Math.max(textWidth(t.label) + 8, textWidth(t.value, 2) + 6)), W - 2 * PAD, gap)
  let x = PAD
  words.forEach((t, i) => {
    const w = ws[i] ?? 0
    const s = saves[i]
    if (s?.proficient) p.framed(x, PAD, w, 23, 1, C.green, C.inset)
    else p.stepped(x, PAD, w, 23, C.inset, 2)
    p.text(t.label, x + Math.floor((w - textWidth(t.label)) / 2), PAD + 3, 1, s?.proficient ? C.ink : C.dim)
    p.text(t.value, x + Math.floor((w - textWidth(t.value, 2)) / 2), PAD + 10, 2, s?.pending ? C.dim : C.ink)
    if (s?.pending) p.text('?', x + 2, PAD + 2, 1, C.amber)
    x += w + gap
  })
  return framedSvg(p, W, PAD + 23 + PAD, scale)
}

/** Inline pips beside a word (a resource, a spell level), with no panel: they read on light and dark. */
export function pipsSvg(left: number, max: number, colour: number, scale: number): { source: string; width: number; height: number } {
  const p = painter()
  const w = Math.max(1, Math.min(max, MAX_PIPS) * PIP_STEP - 2)
  pips(p, left, max, colour, 0, 0)
  return { source: p.svg(w, PIP, scale), width: w * scale, height: PIP * scale }
}

